import type { Question } from '../../lib/types'

export const network_performance_questions: Question[] = [
  { id: 'd3-net-001', domain: 3, topics: ['VPC', 'bandwidth', 'VPC peering vs Transit Gateway'], type: 'single', stem: 'A company has 50 VPCs that need full-mesh connectivity. Using VPC peering would require creating 1,225 peering connections. What simplifies this?', options: [{ id: 'A', text: 'Increase the VPC peering limit' }, { id: 'B', text: 'AWS Transit Gateway — hub-and-spoke model connects all VPCs to one TGW; attach each VPC once' }, { id: 'C', text: 'VPC sharing (Resource Access Manager)' }, { id: 'D', text: 'VPN connections between VPCs' }], correct: ['B'], explanation: 'Transit Gateway provides a hub-and-spoke network topology. Each VPC attaches to the TGW. All VPCs can communicate through the TGW without direct peering connections. n(n-1)/2 peering connections → n attachments.', distractors: { A: 'VPC peering limits exist (125 per VPC) and managing 1,225 connections is operationally complex.', C: 'VPC sharing shares subnets within an Organization — doesn\'t provide routing between separate VPCs.', D: 'VPN between VPCs adds latency and management overhead — TGW is the scalable solution.' } },
  { id: 'd3-net-002', domain: 3, topics: ['Direct Connect', 'bandwidth', 'dedicated'], type: 'single', stem: 'A company needs a dedicated, consistent-bandwidth connection to AWS for a latency-sensitive financial application. Internet-based VPN introduces too much jitter. What solution provides a private, consistent connection?', options: [{ id: 'A', text: 'Site-to-Site VPN' }, { id: 'B', text: 'AWS Direct Connect — dedicated physical connection to AWS with consistent latency and up to 100 Gbps bandwidth' }, { id: 'C', text: 'Enhanced networking on EC2' }, { id: 'D', text: 'CloudFront origin access' }], correct: ['B'], explanation: 'Direct Connect provides a dedicated private connection between on-premises and AWS, bypassing the public internet. Consistent latency, low jitter, up to 100 Gbps. Essential for latency-sensitive, high-bandwidth enterprise workloads.', distractors: { A: 'VPN runs over the internet — subject to internet congestion, variable latency, and jitter.', C: 'Enhanced networking is EC2-level — doesn\'t provide on-premises to AWS connectivity.', D: 'CloudFront is a CDN — not a private enterprise connection to AWS.' } },
  { id: 'd3-net-003', domain: 3, topics: ['Global Accelerator', 'performance', 'anycast'], type: 'single', stem: 'A global application needs to improve performance for users far from the AWS region. The solution should leverage the AWS private network rather than the public internet. What service provides this?', options: [{ id: 'A', text: 'CloudFront CDN' }, { id: 'B', text: 'AWS Global Accelerator — routes traffic from the nearest edge to the application over the AWS backbone network' }, { id: 'C', text: 'Route 53 latency routing' }, { id: 'D', text: 'NAT Gateway' }], correct: ['B'], explanation: 'Global Accelerator uses Anycast IPs to route user traffic to the nearest AWS edge location, then routes over the AWS private backbone to the application region. Avoids public internet congestion for the majority of the path.', distractors: { A: 'CloudFront caches content at edge locations — suited for static content delivery, not arbitrary application traffic.', C: 'Route 53 latency routing uses DNS — still uses the public internet for the network path.', D: 'NAT Gateway provides outbound internet access — not performance acceleration.' } },
  { id: 'd3-net-004', domain: 3, topics: ['VPC', 'PrivateLink', 'Interface endpoints'], type: 'single', stem: 'A company hosts an API service in their VPC and wants customers from other VPCs (possibly different AWS accounts) to access it privately without internet exposure or VPC peering. What enables this?', options: [{ id: 'A', text: 'VPC peering for each customer' }, { id: 'B', text: 'AWS PrivateLink — expose service via Network Load Balancer, customers create Interface Endpoints in their VPCs' }, { id: 'C', text: 'Internet Gateway for the service VPC' }, { id: 'D', text: 'Site-to-Site VPN' }], correct: ['B'], explanation: 'AWS PrivateLink (VPC Endpoint Services) exposes a service via a NLB. Consumers create an Interface Endpoint (ENI) in their VPC. Traffic flows privately within the AWS network — no internet, no VPC peering, no overlapping CIDR concern.', distractors: { A: 'VPC peering requires non-overlapping CIDRs and shares full routing between VPCs — PrivateLink is more targeted.', C: 'Internet Gateway exposes services publicly — not a private connectivity solution.', D: 'Site-to-Site VPN connects on-premises to AWS — not VPC-to-VPC service access.' } },
  { id: 'd3-net-005', domain: 3, topics: ['Direct Connect', 'LAG', 'bandwidth aggregation'], type: 'single', stem: 'A company has a 1 Gbps Direct Connect connection but needs more bandwidth without changing the physical connection. What aggregates multiple Direct Connect connections?', options: [{ id: 'A', text: 'Increase the MTU on Direct Connect' }, { id: 'B', text: 'Direct Connect Link Aggregation Group (LAG) — bonds multiple connections into a single logical interface for higher throughput' }, { id: 'C', text: 'Add a second Virtual Private Gateway' }, { id: 'D', text: 'Use Direct Connect Gateway' }], correct: ['B'], explanation: 'Direct Connect LAG combines multiple physical connections (same speed, same Direct Connect location) into a single logical connection. 4 × 1 Gbps = 4 Gbps LAG. Active-active for load balancing; if one fails, others continue.', distractors: { A: 'MTU setting affects packet sizes — not aggregate bandwidth.', C: 'Multiple VPGs don\'t aggregate bandwidth — they provide separate routing domains.', D: 'Direct Connect Gateway connects to multiple VPCs — not a bandwidth aggregation feature.' } },
  { id: 'd3-net-006', domain: 3, topics: ['Transit Gateway', 'multicast', 'performance'], type: 'single', stem: 'A media company streams live video and needs to distribute a single video stream to thousands of EC2 instances simultaneously without sending individual copies to each instance. What Transit Gateway feature supports this?', options: [{ id: 'A', text: 'Transit Gateway with standard unicast routing' }, { id: 'B', text: 'Transit Gateway multicast — supports native multicast for one-to-many delivery across VPCs' }, { id: 'C', text: 'CloudFront for video distribution' }, { id: 'D', text: 'VPC peering for each EC2 instance' }], correct: ['B'], explanation: 'Transit Gateway multicast support enables multicast routing across VPC attachments. A single stream is replicated by the network infrastructure rather than by the sender. Reduces bandwidth and eliminates the need for application-level replication.', distractors: { A: 'Standard unicast routing requires sending individual copies to each receiver — not efficient for thousands of receivers.', C: 'CloudFront delivers cached content via HTTP — not real-time multicast for instance-to-instance data distribution.', D: 'Peering for each instance scales poorly and doesn\'t solve multicast.' } },
  { id: 'd3-net-007', domain: 3, topics: ['VPC', 'network peering', 'bandwidth'], type: 'single', stem: 'VPC peering between two VPCs carries critical business traffic. Does VPC peering use the same network path as the public internet?', options: [{ id: 'A', text: 'Yes — VPC peering traffic uses the public internet' }, { id: 'B', text: 'No — VPC peering uses the AWS backbone network, staying within AWS infrastructure' }, { id: 'C', text: 'VPC peering only works within the same AZ' }, { id: 'D', text: 'VPC peering goes over a VPN tunnel' }], correct: ['B'], explanation: 'VPC peering traffic always stays on the AWS global network backbone — it never traverses the public internet. This provides consistent, low-latency, high-bandwidth connectivity between VPCs.', distractors: { A: 'VPC peering uses AWS private network — not the public internet.', C: 'VPC peering works across AZs and regions (inter-region peering).', D: 'VPC peering is direct routing — no VPN tunnels involved.' } },
  { id: 'd3-net-008', domain: 3, topics: ['Direct Connect', 'virtual interfaces', 'public VIF'], type: 'single', stem: 'A company has Direct Connect. They want to access AWS public services (S3, DynamoDB) privately without going through the internet. What Direct Connect Virtual Interface type enables access to public AWS services?', options: [{ id: 'A', text: 'Private VIF — connects to a VPC' }, { id: 'B', text: 'Public VIF — provides access to all AWS public services using their public IP space' }, { id: 'C', text: 'Transit VIF — connects to Transit Gateway' }, { id: 'D', text: 'Hosted VIF from a Direct Connect partner' }], correct: ['B'], explanation: 'Public VIF connects to AWS public service endpoints (S3, EC2 public IPs, DynamoDB, etc.) using AWS public IP addresses, but traffic flows over the Direct Connect private link — not the internet. Provides private access to public AWS services.', distractors: { A: 'Private VIF connects to a specific VPC via VGW — not public AWS services.', C: 'Transit VIF connects to Transit Gateway for VPC routing — not public service access.', D: 'Hosted VIF is a share arrangement from a partner — the VIF type (public/private/transit) still matters.' } },
  { id: 'd3-net-009', domain: 3, topics: ['Site-to-Site VPN', 'accelerated VPN', 'Global Accelerator'], type: 'single', stem: 'A VPN connection to AWS has high latency for international offices. What optimization improves VPN performance for global users?', options: [{ id: 'A', text: 'Increase the VPN bandwidth allocation' }, { id: 'B', text: 'Accelerated Site-to-Site VPN — routes VPN traffic through Global Accelerator edge locations to reduce latency' }, { id: 'C', text: 'Switch to Direct Connect for all offices' }, { id: 'D', text: 'Use split tunneling' }], correct: ['B'], explanation: 'Accelerated Site-to-Site VPN routes VPN traffic from the office through the nearest AWS Global Accelerator edge location, then over the AWS backbone to the VPC. Reduces the internet path length for international VPN connections.', distractors: { A: 'VPN bandwidth is determined by the internet connection — AWS doesn\'t allocate specific bandwidth per VPN.', C: 'Direct Connect requires physical hardware installation at each office — not practical for all global offices.', D: 'Split tunneling routes some traffic directly to the internet and some through VPN — reduces VPN load but doesn\'t improve VPN performance itself.' } },
  { id: 'd3-net-010', domain: 3, topics: ['VPC', 'peering', 'transitive', 'limitations'], type: 'single', stem: 'VPC A is peered with VPC B, and VPC B is peered with VPC C. Can VPC A communicate with VPC C through VPC B?', options: [{ id: 'A', text: 'Yes — traffic flows: A → B → C' }, { id: 'B', text: 'No — VPC peering is non-transitive; A and C need a direct peering connection or use Transit Gateway' }, { id: 'C', text: 'Yes, but only with specific route table entries' }, { id: 'D', text: 'Yes, if VPC B acts as a hub' }], correct: ['B'], explanation: 'VPC peering is non-transitive — a key exam concept. VPC A can only communicate with VPC B directly. For A-C communication, either create a direct A-C peering connection or use Transit Gateway (which supports transitive routing).', distractors: { A: 'Transitive routing through VPC peering is not supported — traffic from A cannot flow through B to reach C.', C: 'Route tables cannot enable transitive peering — it\'s a fundamental architecture constraint.', D: 'Even with VPC B as a "hub," peering is non-transitive — Transit Gateway is required for hub-and-spoke routing.' } },
  { id: 'd3-net-011', domain: 3, topics: ['CloudFront', 'origin shield', 'bandwidth'], type: 'single', stem: 'A CloudFront distribution serves files from an S3 origin in us-east-1. Global edge locations generate many cache-miss requests to the origin. What reduces origin request count?', options: [{ id: 'A', text: 'Increase CloudFront TTL' }, { id: 'B', text: 'Enable CloudFront Origin Shield — additional regional caching layer that reduces requests to the origin by up to 90%' }, { id: 'C', text: 'Add more edge locations' }, { id: 'D', text: 'Use multiple S3 origins' }], correct: ['B'], explanation: 'Origin Shield acts as a centralized cache between all global edge locations and the origin. Cache misses from edges check Origin Shield before going to the origin. Significantly reduces origin load and bandwidth costs.', distractors: { A: 'Longer TTL helps but depends on content being cacheable — Origin Shield helps regardless of TTL.', C: 'More edge locations distribute user traffic — doesn\'t reduce the total origin requests from cache misses.', D: 'Multiple origins add redundancy — don\'t reduce per-origin request volume.' } },
  { id: 'd3-net-012', domain: 3, topics: ['Network Firewall', 'inspection', 'performance'], type: 'single', stem: 'A company needs deep packet inspection and stateful firewall rules for their VPC traffic at high throughput without managing firewall infrastructure. What AWS service provides this?', options: [{ id: 'A', text: 'Security Groups (stateful at instance level)' }, { id: 'B', text: 'AWS Network Firewall — managed stateful/stateless inspection for VPC traffic, supports IPS rules, scales automatically' }, { id: 'C', text: 'Network ACLs (stateless)' }, { id: 'D', text: 'WAF (Web Application Firewall)' }], correct: ['B'], explanation: 'AWS Network Firewall is a managed service for VPC-level stateful network inspection, including deep packet inspection, IPS/IDS rules (Suricata), domain filtering, and TLS inspection. Scales to handle Gbps of traffic without managing firewall instances.', distractors: { A: 'Security groups are instance-level stateful rules — no deep packet inspection or IPS.', C: 'NACLs are subnet-level stateless rules — no DPI or IPS capabilities.', D: 'WAF handles HTTP/HTTPS application-layer attacks — not general deep packet inspection.' } },
  { id: 'd3-net-013', domain: 3, topics: ['GWLB', 'appliance insertion', 'inline'], type: 'single', stem: 'A company wants to transparently route all VPC traffic through third-party security appliances (NGFW, IDS/IPS) for inspection without modifying applications. What AWS service provides transparent inline appliance insertion?', options: [{ id: 'A', text: 'ALB with appliance target groups' }, { id: 'B', text: 'Gateway Load Balancer (GWLB) — distributes traffic to appliance fleet using GENEVE encapsulation, returns traffic to original destination' }, { id: 'C', text: 'NLB in front of appliances' }, { id: 'D', text: 'Transit Gateway policy routing' }], correct: ['B'], explanation: 'GWLB is designed for inline appliance insertion. Using GENEVE encapsulation, it distributes traffic to a fleet of appliances (preserving original IP headers), receives inspected traffic back, and returns it to the original destination — transparent to applications.', distractors: { A: 'ALB for appliances requires changing application routing — not transparent to applications.', C: 'NLB routes to appliances but doesn\'t handle the return path transparently.', D: 'TGW policy routing can steer traffic but doesn\'t handle the return path for inline inspection.' } },
  { id: 'd3-net-014', domain: 3, topics: ['VPN', 'ECMP', 'throughput'], type: 'single', stem: 'A Site-to-Site VPN connection provides up to 1.25 Gbps per tunnel. A company needs more than 1.25 Gbps. What configuration increases VPN throughput?', options: [{ id: 'A', text: 'Increase the VPN encryption strength for more throughput' }, { id: 'B', text: 'Use Transit Gateway with multiple VPN connections and ECMP — each VPN adds 1.25 Gbps; aggregate throughput scales linearly' }, { id: 'C', text: 'Use a Dedicated Host for VPN' }, { id: 'D', text: 'Switch to TLS VPN' }], correct: ['B'], explanation: 'Transit Gateway supports Equal-Cost Multi-Path (ECMP) routing across multiple VPN connections. With 4 VPN connections and ECMP, you can achieve ~5 Gbps. Each VPN connection has two tunnels (active-active with ECMP = 2.5 Gbps per VPN).', distractors: { A: 'Encryption strength affects CPU usage — not the throughput limit.', C: 'Dedicated Hosts are for EC2 licensing — no impact on VPN throughput.', D: 'AWS VPN uses IPsec — TLS VPN is a different product category.' } },
  { id: 'd3-net-015', domain: 3, topics: ['Route 53', 'low TTL', 'performance'], type: 'single', stem: 'An application uses Route 53 with a 60-second TTL. Every DNS query adds latency for users whose local DNS cache has expired. What reduces this DNS resolution overhead?', options: [{ id: 'A', text: 'Increase TTL to 24 hours to reduce query frequency' }, { id: 'B', text: 'Route 53 Resolver DNS Firewall' }, { id: 'C', text: 'Enable Route 53 query logging' }, { id: 'D', text: 'Route 53 Resolver cache size has no user-facing impact' }], correct: ['A'], explanation: 'Longer TTL reduces DNS query frequency — users\' local DNS resolvers cache the answer longer, avoiding repeated Route 53 lookups. For stable endpoints, increase TTL (e.g., 300-3600 seconds). Trade-off: slower DNS change propagation.', distractors: { B: 'DNS Firewall filters DNS queries for security — doesn\'t reduce latency from TTL expiry.', C: 'Query logging captures DNS activity — doesn\'t improve performance.', D: 'DNS resolution adds latency every time the TTL expires — TTL length directly affects how often this happens.' } },
  { id: 'd3-net-016', domain: 3, topics: ['VPC', 'subnets', 'availability'], type: 'single', stem: 'A company deploys EC2 instances in a single subnet in one AZ. What is the minimum change to make the architecture resilient to AZ failures?', options: [{ id: 'A', text: 'Add a second EC2 instance in the same subnet' }, { id: 'B', text: 'Create subnets in at least 2 different AZs and deploy instances across them with an ALB' }, { id: 'C', text: 'Enable enhanced networking on the existing instances' }, { id: 'D', text: 'Use a larger instance type' }], correct: ['B'], explanation: 'AZ resilience requires distributing instances across multiple AZs. Create subnets in 2+ AZs, deploy instances in each, and use an ALB or NLB to distribute traffic. If one AZ fails, instances in other AZs continue serving traffic.', distractors: { A: 'Multiple instances in the same AZ all fail if that AZ has an outage.', C: 'Enhanced networking improves bandwidth — doesn\'t provide AZ fault tolerance.', D: 'Instance size doesn\'t prevent AZ failures.' } },
  { id: 'd3-net-017', domain: 3, topics: ['Transit Gateway', 'route tables', 'segmentation'], type: 'single', stem: 'A company has production and development VPCs attached to Transit Gateway. Production VPCs should not be able to communicate with development VPCs. How is this network segmentation configured?', options: [{ id: 'A', text: 'Transit Gateway doesn\'t support network segmentation' }, { id: 'B', text: 'Create separate Transit Gateway route tables for prod and dev — control which VPCs can route to each other via route table association and propagation' }, { id: 'C', text: 'Use security groups to block prod-dev traffic' }, { id: 'D', text: 'Create separate Transit Gateways' }], correct: ['B'], explanation: 'TGW route tables provide network segmentation. Create separate route tables for production and development. Associate production VPCs with the prod route table (which doesn\'t have routes to dev VPCs) and vice versa.', distractors: { A: 'Transit Gateway route tables specifically enable network segmentation — a core TGW feature.', C: 'Security groups are instance-level — they don\'t provide network-level routing segmentation.', D: 'Separate TGWs work but are more expensive and complex — TGW route tables solve this within one TGW.' } },
  { id: 'd3-net-018', domain: 3, topics: ['CloudFront', 'compression', 'performance'], type: 'single', stem: 'A CloudFront distribution serves HTML, CSS, and JavaScript files. Browsers support gzip and Brotli compression. How can CloudFront reduce file transfer sizes?', options: [{ id: 'A', text: 'CloudFront doesn\'t support compression' }, { id: 'B', text: 'Enable CloudFront automatic compression — compresses eligible files (text-based) if the request includes Accept-Encoding header' }, { id: 'C', text: 'Compress files in S3 before uploading' }, { id: 'D', text: 'Use binary protocol instead of HTTP' }], correct: ['B'], explanation: 'CloudFront can automatically compress files (HTML, CSS, JS, JSON) using gzip or Brotli when clients send Accept-Encoding headers. Compression happens at the edge — reduces transferred bytes and improves load times. CloudFront caches both compressed and uncompressed versions.', distractors: { A: 'CloudFront does support automatic compression — it\'s a cache behavior setting.', C: 'Pre-compressed files in S3 work but require Content-Encoding headers — CloudFront auto-compression handles this at the edge without S3 changes.', D: 'HTTP/2 and HTTP/3 provide binary protocol performance benefits, but CloudFront compression refers to content compression.' } },
  { id: 'd3-net-019', domain: 3, topics: ['Direct Connect', 'resilience', 'redundancy'], type: 'single', stem: 'A company has a single Direct Connect connection. For high availability, what is the minimum additional infrastructure needed for resilience against single connection failure?', options: [{ id: 'A', text: 'Add a second Virtual Private Gateway' }, { id: 'B', text: 'A second Direct Connect connection (different device, ideally different location) for active-active or active-passive failover' }, { id: 'C', text: 'Enable Multi-AZ on the Direct Connect connection' }, { id: 'D', text: 'Increase the bandwidth of the existing connection' }], correct: ['B'], explanation: 'AWS recommends two Direct Connect connections to separate devices for HA. For maximum resilience, connections to different Direct Connect locations. Add a Site-to-Site VPN as a backup for DR if a second DX is too expensive.', distractors: { A: 'A second VGW adds routing options but doesn\'t protect against the physical DX connection failure.', C: 'Direct Connect doesn\'t have Multi-AZ — it\'s a physical connection at a specific location.', D: 'Bandwidth increase doesn\'t protect against connection failure.' } },
  { id: 'd3-net-020', domain: 3, topics: ['VPC Flow Logs', 'performance debugging'], type: 'single', stem: 'A network team needs to investigate intermittent packet drops within a VPC. Which tool captures accepted and rejected network traffic for analysis?', options: [{ id: 'A', text: 'CloudTrail API logs' }, { id: 'B', text: 'VPC Flow Logs — captures IP traffic information for network interfaces, subnets, or VPCs' }, { id: 'C', text: 'AWS X-Ray' }, { id: 'D', text: 'CloudWatch application metrics' }], correct: ['B'], explanation: 'VPC Flow Logs record information about all IP traffic (source/dest IP, port, protocol, action ACCEPT/REJECT, bytes) for ENIs, subnets, or entire VPCs. Essential for network troubleshooting, security analysis, and compliance.', distractors: { A: 'CloudTrail logs AWS API calls — not IP-level network traffic.', C: 'X-Ray traces application-level requests — not network packet-level analysis.', D: 'CloudWatch metrics show aggregate service metrics — not individual packet-level flow data.' } },
  { id: 'd3-net-021', domain: 3, topics: ['Transit Gateway', 'Connect', 'SD-WAN'], type: 'single', stem: 'A company uses an SD-WAN appliance in their VPC for branch connectivity. They need to connect the SD-WAN to Transit Gateway with high bandwidth (up to 20 Gbps) without a physical Direct Connect port. What attachment type enables this?', options: [{ id: 'A', text: 'VPN attachment (IPsec) — max 1.25 Gbps per tunnel' }, { id: 'B', text: 'Transit Gateway Connect — GRE-based high-bandwidth attachment for SD-WAN and virtual appliances up to 20 Gbps' }, { id: 'C', text: 'Direct Connect VIF to TGW' }, { id: 'D', text: 'VPC Peering to the SD-WAN VPC' }], correct: ['B'], explanation: 'TGW Connect attachment uses Generic Routing Encapsulation (GRE) for high-bandwidth connectivity between TGW and SD-WAN/virtual appliances running in a VPC. Provides up to 20 Gbps per Connect attachment.', distractors: { A: 'VPN/IPsec is limited to 1.25 Gbps per tunnel — insufficient for high-bandwidth SD-WAN requirements.', C: 'Direct Connect VIF requires physical hardware at a DX location — not virtual appliance in VPC.', D: 'VPC peering connects VPCs — doesn\'t provide SD-WAN-to-TGW network connectivity.' } },
  { id: 'd3-net-022', domain: 3, topics: ['VPC', 'Reachability Analyzer'], type: 'single', stem: 'A developer cannot connect to an EC2 instance from outside the VPC. Security groups, NACLs, and route tables may all have configuration errors. What tool analyzes the network path and identifies the specific blocking configuration?', options: [{ id: 'A', text: 'VPC Flow Logs' }, { id: 'B', text: 'VPC Reachability Analyzer — analyzes network topology and identifies which configuration component is blocking connectivity' }, { id: 'C', text: 'AWS X-Ray' }, { id: 'D', text: 'CloudWatch network metrics' }], correct: ['B'], explanation: 'VPC Reachability Analyzer performs network topology analysis between a source and destination. It identifies which specific security group rule, NACL, route table, or missing Internet Gateway is blocking the path — without sending test traffic.', distractors: { A: 'Flow Logs show actual traffic flow (or absence) — Reachability Analyzer performs pre-traffic topology analysis.', C: 'X-Ray traces application requests — not network topology analysis.', D: 'CloudWatch metrics show aggregates — not path-specific blocking analysis.' } },
  { id: 'd3-net-023', domain: 3, topics: ['PrivateLink', 'DNS', 'endpoint'], type: 'single', stem: 'An EC2 instance uses a VPC Interface Endpoint for S3. DNS resolution for s3.amazonaws.com must resolve to the interface endpoint private IP (not S3 public IPs). What DNS configuration is required?', options: [{ id: 'A', text: 'No configuration needed — interface endpoints handle DNS automatically' }, { id: 'B', text: 'Enable Private DNS name for the VPC interface endpoint — Route 53 Resolver returns the endpoint ENI IP for the service hostname' }, { id: 'C', text: 'Add a custom Route 53 record for s3.amazonaws.com' }, { id: 'D', text: 'Update the EC2 instance /etc/hosts file' }], correct: ['B'], explanation: 'Enable Private DNS on the interface endpoint. The VPC\'s Route 53 Resolver returns the endpoint ENI IP for s3.amazonaws.com queries from within the VPC. No application code changes — the service hostname resolves to the private endpoint.', distractors: { A: 'Private DNS is not enabled by default — it must be explicitly enabled on the endpoint.', C: 'Custom Route 53 records would require maintaining DNS alongside the endpoint lifecycle.', D: '/etc/hosts modification requires updating every instance — not scalable.' } },
  { id: 'd3-net-024', domain: 3, topics: ['CloudFront', 'HTTP/2', 'HTTP/3', 'QUIC'], type: 'single', stem: 'A mobile application using CloudFront experiences performance issues on high-latency networks. HTTP/2 is enabled. What newer protocol further reduces latency on lossy/high-latency mobile connections?', options: [{ id: 'A', text: 'HTTP/1.1 with connection reuse' }, { id: 'B', text: 'HTTP/3 (QUIC) — UDP-based protocol with 0-RTT handshakes and better performance on lossy networks' }, { id: 'C', text: 'WebSocket for all requests' }, { id: 'D', text: 'TLS 1.3 only' }], correct: ['B'], explanation: 'HTTP/3 (QUIC) uses UDP instead of TCP. Benefits: 0-RTT connection resumption, no head-of-line blocking, better performance on lossy mobile networks (packet loss affects one stream, not all). CloudFront supports HTTP/3 (QUIC) opt-in.', distractors: { A: 'HTTP/1.1 is slower than HTTP/2 — HTTP/3 is the next evolution.', C: 'WebSocket is for persistent bidirectional connections — not a general HTTP performance protocol.', D: 'TLS 1.3 reduces handshake round trips — QUIC/HTTP/3 provides additional protocol-level improvements.' } },
  { id: 'd3-net-025', domain: 3, topics: ['VPC', 'NAT Gateway', 'bandwidth'], type: 'single', stem: 'Private EC2 instances use NAT Gateway for internet access. Outbound bandwidth is consistently hitting the NAT Gateway limit (45 Gbps). How can more bandwidth be achieved?', options: [{ id: 'A', text: 'NAT Gateways scale automatically beyond 45 Gbps' }, { id: 'B', text: 'Create NAT Gateways in multiple AZs and distribute private instances across AZs — each NAT Gateway provides up to 45 Gbps independently' }, { id: 'C', text: 'Enable enhanced networking on the NAT Gateway' }, { id: 'D', text: 'Use an Internet Gateway instead' }], correct: ['B'], explanation: 'Each NAT Gateway provides up to 45 Gbps. To increase aggregate throughput, distribute instances across multiple AZs, each with their own NAT Gateway. Instances in us-east-1a route through the 1a NAT GW, instances in 1b through 1b NAT GW, etc.', distractors: { A: 'NAT Gateways don\'t scale beyond 45 Gbps per gateway — but multiple gateways provide higher aggregate throughput.', C: 'NAT Gateways are managed services — no user-controllable network settings.', D: 'IGW provides public IP routing — private instances typically can\'t use IGW directly.' } },
  { id: 'd3-net-026', domain: 3, topics: ['Site-to-Site VPN', 'IKEv2', 'Dead Peer Detection'], type: 'single', stem: 'A Site-to-Site VPN frequently has tunnels that go down without notification, requiring manual restart. What VPN features improve tunnel reliability?', options: [{ id: 'A', text: 'Use route-based VPN instead of policy-based' }, { id: 'B', text: 'Enable Dead Peer Detection (DPD) and IKEv2 — DPD detects dead tunnels and restarts them; IKEv2 provides faster re-keying' }, { id: 'C', text: 'Increase the encryption key size' }, { id: 'D', text: 'Use BGP instead of static routing' }], correct: ['B'], explanation: 'Dead Peer Detection sends periodic keepalives. If no response after DPD timeout, VPN reinitiates the tunnel automatically. IKEv2 provides more efficient re-keying and better reliability than IKEv1. Reduces manual intervention.', distractors: { A: 'Route-based VPN is more flexible — doesn\'t specifically improve tunnel failure detection.', C: 'Larger keys impact performance — don\'t improve tunnel reliability.', D: 'BGP enables dynamic routing — doesn\'t detect or recover from dead VPN tunnels.' } },
  { id: 'd3-net-027', domain: 3, topics: ['Inter-region', 'data transfer', 'cost'], type: 'single', stem: 'A company has VPC peering between us-east-1 and eu-west-1 to transfer data. What is the cost implication of inter-region VPC peering data transfer?', options: [{ id: 'A', text: 'Inter-region peering data transfer is free' }, { id: 'B', text: 'Inter-region peering data transfer is charged at standard cross-region rates (approximately $0.02/GB each direction)' }, { id: 'C', text: 'Only inbound transfers are charged' }, { id: 'D', text: 'Data transfer is free within the AWS network' }], correct: ['B'], explanation: 'Cross-region data transfer over VPC peering is NOT free. Standard inter-region data transfer rates apply in both directions. This is a common cost optimization topic — consider data locality to minimize cross-region transfers.', distractors: { A: 'Same-region peering is free; cross-region peering incurs data transfer charges.', C: 'Both inbound and outbound cross-region data transfer are charged.', D: '"Within the AWS network" doesn\'t mean cross-region is free — only intra-AZ/intra-VPC transfers within the same region may be free.' } },
  { id: 'd3-net-028', domain: 3, topics: ['CloudFront', 'cache behavior', 'cookies'], type: 'single', stem: 'A CloudFront distribution is not caching responses because the application sets many cookies (authentication, tracking, preferences). How can caching be improved without breaking authentication?', options: [{ id: 'A', text: 'Remove all cookies from the application' }, { id: 'B', text: 'Configure CloudFront cache policy to forward only the specific cookies the application uses for content variation — exclude tracking/analytics cookies from cache key' }, { id: 'C', text: 'Disable CloudFront cookies entirely' }, { id: 'D', text: 'Use signed cookies for all requests' }], correct: ['B'], explanation: 'Configure the cache policy to include only the cookies that affect content (e.g., language preference) in the cache key. Exclude analytics/tracking cookies. Separate the cache key (content determination) from cookies forwarded to origin.', distractors: { A: 'Removing cookies would break authentication and personalization.', C: 'Disabling cookie forwarding would break auth — the goal is selective forwarding.', D: 'Signed cookies control access to content — not a cache behavior optimization.' } },
  { id: 'd3-net-029', domain: 3, topics: ['VPC', 'routing', 'longest prefix match'], type: 'single', stem: 'A route table has two entries: 10.0.0.0/8 → Transit Gateway and 10.1.0.0/16 → VPC Peering. A packet destined for 10.1.2.3 — which route is used?', options: [{ id: 'A', text: '10.0.0.0/8 → Transit Gateway (less specific but listed first)' }, { id: 'B', text: '10.1.0.0/16 → VPC Peering (longest prefix match — more specific route wins)' }, { id: 'C', text: 'The packet is dropped (conflict)' }, { id: 'D', text: 'Both routes are used (load balanced)' }], correct: ['B'], explanation: 'IP routing uses longest prefix match: the most specific (longest prefix length) matching route wins. 10.1.0.0/16 is more specific than 10.0.0.0/8 for destination 10.1.2.3. The VPC Peering route is selected.', distractors: { A: 'Route order doesn\'t determine selection — longest prefix match is the rule.', C: 'Overlapping routes are valid in IP routing — longest prefix match resolves the selection.', D: 'IP routing doesn\'t load balance across overlapping routes — longest prefix match selects one route.' } },
  { id: 'd3-net-030', domain: 3, topics: ['Elastic Load Balancer', 'connection draining', 'performance'], type: 'single', stem: 'During Auto Scaling scale-in events, EC2 instances are immediately terminated even if they have active connections, causing request errors. What ALB feature gracefully handles this?', options: [{ id: 'A', text: 'ALB health checks' }, { id: 'B', text: 'Deregistration delay — ALB continues sending existing connections to deregistering instances for a configurable period before terminating' }, { id: 'C', text: 'Sticky sessions' }, { id: 'D', text: 'ALB multi-value headers' }], correct: ['B'], explanation: 'Deregistration delay (connection draining) allows in-flight requests to complete. When an instance deregisters, the ALB stops sending NEW requests but allows existing connections to complete, up to the delay timeout (default 300 seconds, configurable 0-3600).', distractors: { A: 'Health checks determine if an instance is healthy — not how in-flight connections are handled during deregistration.', C: 'Sticky sessions bind users to specific instances — doesn\'t help during termination.', D: 'Multi-value headers allow multiple header values to be forwarded — not related to connection draining.' } },
  { id: 'd3-net-031', domain: 3, topics: ['Direct Connect', 'Gateway', 'multiple VPCs'], type: 'single', stem: 'A company has Direct Connect and multiple VPCs in different regions. They want a single Direct Connect connection to access all VPCs across regions. What connects a single DX to multiple VPCs?', options: [{ id: 'A', text: 'One Virtual Private Gateway per VPC (up to 10 VPCs per connection)' }, { id: 'B', text: 'Direct Connect Gateway — single private VIF attached to DX Gateway; associates with VGWs/TGWs across multiple regions' }, { id: 'C', text: 'VPN connections from DX to each VPC' }, { id: 'D', text: 'Cross-region VPC peering from the directly connected VPC' }], correct: ['B'], explanation: 'Direct Connect Gateway provides global connectivity: one private VIF connects to DX Gateway, which can be associated with VGWs or TGWs in multiple regions. A single DX connection can reach up to 10 TGWs or 20 VGWs.', distractors: { A: 'One VGW per VPC works but is limited to VPCs in the same region as the DX connection — DX Gateway is cross-region.', C: 'VPN over DX adds complexity — DX Gateway provides native cross-region connectivity.', D: 'Cross-region peering from a connected VPC requires additional routing configuration and doesn\'t scale.' } },
  { id: 'd3-net-032', domain: 3, topics: ['Network ACL', 'ephemeral ports', 'stateless'], type: 'single', stem: 'An EC2 instance in a subnet with a Network ACL sends a request to the internet. The NACL inbound rules don\'t allow return traffic. Why is the instance not receiving responses?', options: [{ id: 'A', text: 'NACLs are stateful — they automatically allow return traffic' }, { id: 'B', text: 'NACLs are stateless — return traffic uses ephemeral ports (1024-65535) and needs an explicit inbound ALLOW rule for those ports' }, { id: 'C', text: 'The Internet Gateway is blocking return traffic' }, { id: 'D', text: 'Security groups are blocking the return traffic' }], correct: ['B'], explanation: 'NACLs are stateless — outbound requests don\'t create state for return traffic. Return traffic arrives on ephemeral ports (random high ports). The NACL must explicitly allow inbound traffic on ports 1024-65535 (or the specific ephemeral range) for responses.', distractors: { A: 'Security groups are stateful (return traffic automatically allowed) — NACLs are stateless.', C: 'Internet Gateways don\'t filter traffic — they route packets.', D: 'Security groups are stateful and would allow return traffic — NACLs are the culprit here.' } },
  { id: 'd3-net-033', domain: 3, topics: ['CloudFront', 'geo restriction', 'access control'], type: 'single', stem: 'A streaming service has licensing restrictions preventing content delivery in specific countries. How can CloudFront enforce geographic content restrictions?', options: [{ id: 'A', text: 'Route 53 geolocation routing' }, { id: 'B', text: 'CloudFront geo restriction — block or allow content delivery to specific countries based on viewer location' }, { id: 'C', text: 'WAF geographic match condition' }, { id: 'D', text: 'Lambda@Edge IP geolocation lookup' }], correct: ['B'], explanation: 'CloudFront geo restriction uses a list of countries to either whitelist (allow only listed countries) or blacklist (block listed countries). Based on viewer\'s IP → country determination. Simpler than WAF or Lambda@Edge for straightforward geographic blocking.', distractors: { A: 'Route 53 geolocation routing controls DNS routing — doesn\'t restrict CloudFront content delivery.', C: 'WAF geographic match works but is more complex and adds cost vs. native CloudFront geo restriction.', D: 'Lambda@Edge can do geolocation but requires code — CloudFront geo restriction is native and configuration-only.' } },
  { id: 'd3-net-034', domain: 3, topics: ['VPC', 'security group', 'reference'], type: 'single', stem: 'A web tier security group should allow inbound traffic only from the load balancer security group. What security group rule achieves this without hardcoding IPs?', options: [{ id: 'A', text: 'Allow inbound from the load balancer\'s Elastic IP' }, { id: 'B', text: 'Reference the ALB security group ID as the source — the rule allows traffic from all IPs in that security group' }, { id: 'C', text: 'Allow all inbound from 0.0.0.0/0' }, { id: 'D', text: 'Use NACLs to restrict to load balancer IPs' }], correct: ['B'], explanation: 'Security groups can reference other security groups as the source/destination. Allows traffic only from instances (or load balancers) that belong to the referenced security group. No IP addresses to maintain — automatically adapts as ALB nodes change.', distractors: { A: 'ALB IPs change as it scales — hardcoding IPs is not maintainable.', C: '0.0.0.0/0 allows all internet traffic — not restricted to the ALB.', D: 'NACL IP restriction requires maintaining ALB IP ranges which change — security group reference is the clean solution.' } },
  { id: 'd3-net-035', domain: 3, topics: ['VPN', 'BGP', 'dynamic routing'], type: 'single', stem: 'A company has Site-to-Site VPN and wants automatic route propagation when new subnets are added to on-premises. What routing configuration achieves this?', options: [{ id: 'A', text: 'Static routing — add routes manually every time a new subnet is added' }, { id: 'B', text: 'BGP dynamic routing — on-premises router advertises new subnets; AWS VGW automatically learns and propagates routes' }, { id: 'C', text: 'OSPF over VPN' }, { id: 'D', text: 'Route 53 Resolver inbound endpoint' }], correct: ['B'], explanation: 'BGP over VPN enables dynamic route propagation. Enable route propagation on the VPC route table — the VGW automatically populates routes from BGP updates. New on-premises subnets are automatically routed.', distractors: { A: 'Static routing requires manual updates for each new subnet — error-prone and not scalable.', C: 'AWS Site-to-Site VPN supports BGP — not OSPF. OSPF is for internal network routing.', D: 'Route 53 Resolver is for DNS — not VPN route propagation.' } },
  { id: 'd3-net-036', domain: 3, topics: ['VPC', 'Ingress Routing', 'traffic mirroring'], type: 'single', stem: 'A security team needs to capture copies of all network traffic flowing through an EC2 instance for analysis by a third-party IDS without affecting the instance\'s primary traffic path. What VPC feature provides this?', options: [{ id: 'A', text: 'VPC Flow Logs' }, { id: 'B', text: 'VPC Traffic Mirroring — copies traffic from an ENI to an NLB or ENI target for out-of-band analysis' }, { id: 'C', text: 'Amazon GuardDuty' }, { id: 'D', text: 'AWS CloudTrail' }], correct: ['B'], explanation: 'Traffic Mirroring creates a copy of inbound/outbound traffic from a source ENI and sends it to a target (NLB or ENI). The original traffic is unaffected. The IDS appliance receives the mirrored traffic for analysis.', distractors: { A: 'Flow Logs capture metadata (IP, port, protocol, bytes) — not the actual packet payload needed for deep inspection.', C: 'GuardDuty uses threat intelligence and ML for detection — doesn\'t provide raw packet capture for third-party IDS.', D: 'CloudTrail logs AWS API calls — not network packet captures.' } },
  { id: 'd3-net-037', domain: 3, topics: ['VPC Lattice', 'service networking'], type: 'single', stem: 'Multiple teams run microservices in different VPCs and accounts. They need a consistent way to discover, connect, and apply policies to services without managing complex VPC peering or PrivateLink configurations. What new AWS service addresses this?', options: [{ id: 'A', text: 'Transit Gateway for all service traffic' }, { id: 'B', text: 'Amazon VPC Lattice — application-layer networking for consistent service-to-service connectivity with auth, observability, and routing' }, { id: 'C', text: 'Cloud Map for service discovery only' }, { id: 'D', text: 'API Gateway private integrations' }], correct: ['B'], explanation: 'Amazon VPC Lattice provides a consistent application layer networking plane for service-to-service communication across VPCs and accounts. Features: access policies (SigV4 auth), observability (metrics/logs), request routing, and service discovery. Removes need for complex PrivateLink per-service setup.', distractors: { A: 'TGW provides Layer 3 routing — not application-layer policies or service discovery.', C: 'Cloud Map provides service discovery (DNS/API) — doesn\'t handle connectivity, auth policies, or observability.', D: 'API Gateway is a public/private API gateway — not a service mesh for east-west VPC traffic.' } },
  { id: 'd3-net-038', domain: 3, topics: ['CloudFront', 'ttl', 'stale-while-revalidate'], type: 'single', stem: 'A CloudFront distribution has objects with 24-hour TTL. Users are occasionally getting stale content for hours after origin updates. What configuration reduces the maximum stale time?', options: [{ id: 'A', text: 'Increase the TTL to ensure caching' }, { id: 'B', text: 'Lower the TTL and use cache invalidation for immediate updates — or configure origin with Cache-Control headers' }, { id: 'C', text: 'Use signed URLs to bypass cache' }, { id: 'D', text: 'Use a different CloudFront price class' }], correct: ['B'], explanation: 'To reduce stale content: lower TTL (trade-off: more origin requests), use CloudFront invalidations for immediate updates, or have the origin send Cache-Control: max-age=X headers that CloudFront respects (within the min/max TTL range).', distractors: { A: 'Higher TTL makes staleness worse — not better.', C: 'Signed URLs control access — they can bypass cache but it\'s per-request and doesn\'t solve the freshness problem.', D: 'Price class affects which edge locations are used — not content freshness.' } },
  { id: 'd3-net-039', domain: 3, topics: ['VPC', 'IPAM', 'IP management'], type: 'single', stem: 'A company has hundreds of VPCs across multiple AWS accounts. They experience IP address conflicts when new VPCs are created with overlapping CIDR ranges. What service provides centralized IP address management?', options: [{ id: 'A', text: 'Manage CIDRs via spreadsheet' }, { id: 'B', text: 'Amazon VPC IP Address Manager (IPAM) — centralized, automated IP address planning and assignment across accounts and regions' }, { id: 'C', text: 'AWS Organizations for IP management' }, { id: 'D', text: 'Route 53 IPAM records' }], correct: ['B'], explanation: 'Amazon IPAM provides centralized IP address planning, tracking, and enforcement. Assign CIDR pools to AWS Organizations OUs and accounts. IPAM can enforce that VPCs only use CIDRs from their assigned pool, preventing overlaps.', distractors: { A: 'Spreadsheet-based management doesn\'t prevent conflicts and doesn\'t scale.', C: 'Organizations manages accounts — not IP address allocation.', D: 'Route 53 IPAM records don\'t exist — IPAM is a VPC service.' } },
  { id: 'd3-net-040', domain: 3, topics: ['VPC', 'flow logs', 'custom format'], type: 'single', stem: 'A security team needs VPC Flow Logs to include the packet type (IPv4 or IPv6) and the traffic path. Custom format fields beyond the default are needed. Is this supported?', options: [{ id: 'A', text: 'VPC Flow Logs only support the default fixed format' }, { id: 'B', text: 'Yes — VPC Flow Logs support custom log formats with additional fields: traffic-type, pkt-src-aws-service, flow-direction, and more' }, { id: 'C', text: 'Only available for CloudWatch Logs destination, not S3' }, { id: 'D', text: 'Custom fields require AWS Support to enable' }], correct: ['B'], explanation: 'VPC Flow Logs support custom log formats. Choose from available fields including flow direction, traffic type (IPv4/IPv6), source/dest AWS service, TCP flags, and more. Available for both CloudWatch Logs and S3 destinations.', distractors: { A: 'Custom format is supported and commonly used — the default format is just a starting point.', C: 'Custom format works with both CloudWatch Logs and S3 destinations.', D: 'Custom formats are a self-service feature in the console/CLI — no AWS Support required.' } },
  { id: 'd3-net-041', domain: 3, topics: ['Direct Connect', 'hosted connection', 'sub-1Gbps'], type: 'single', stem: 'A company needs 200 Mbps of Direct Connect bandwidth but dedicated connections start at 1 Gbps. What option provides sub-1Gbps Direct Connect?', options: [{ id: 'A', text: 'Dedicated Direct Connect at 1 Gbps minimum' }, { id: 'B', text: 'Direct Connect Hosted Connection — a partner provides a shared connection with capacities from 50 Mbps to 10 Gbps' }, { id: 'C', text: 'AWS VPN with 200 Mbps throttling' }, { id: 'D', text: 'Transit Gateway with bandwidth shaping' }], correct: ['B'], explanation: 'Hosted connections (from AWS Direct Connect Partners) provide sub-1 Gbps capacities (50 Mbps, 100 Mbps, 200 Mbps, 300 Mbps, 400 Mbps, 500 Mbps). The partner owns the dedicated port and allocates capacity to customers.', distractors: { A: 'AWS direct dedicated connections start at 1 Gbps — Hosted Connections via partners provide sub-Gbps.', C: 'Site-to-Site VPN doesn\'t provide consistent bandwidth guarantees like Direct Connect.', D: 'TGW bandwidth shaping is not a Direct Connect bandwidth alternative.' } },
  { id: 'd3-net-042', domain: 3, topics: ['Route 53', 'resolver', 'DNS firewall'], type: 'single', stem: 'An EC2 instance is compromised and making DNS queries to malicious command-and-control domains. How can DNS-level security be enforced in the VPC?', options: [{ id: 'A', text: 'Block outbound port 53 in security groups' }, { id: 'B', text: 'Route 53 Resolver DNS Firewall — define domain allow/block lists; applied to all DNS queries from VPC resources' }, { id: 'C', text: 'Network ACLs blocking DNS' }, { id: 'D', text: 'GuardDuty remediation Lambda' }], correct: ['B'], explanation: 'Route 53 Resolver DNS Firewall allows blocking DNS queries to known malicious domains at the VPC level. Configure block/allow lists (custom or AWS-managed threat intelligence). Applied to all DNS queries from Route 53 Resolver in the VPC.', distractors: { A: 'Blocking port 53 prevents all DNS — breaks legitimate DNS resolution.', C: 'NACLs block all traffic on port 53 — can\'t selectively block specific domain names.', D: 'GuardDuty detects threats — DNS Firewall actively blocks malicious DNS queries.' } },
  { id: 'd3-net-043', domain: 3, topics: ['EC2', 'ENA Express', 'low latency'], type: 'single', stem: 'A latency-sensitive trading application requires the absolute lowest possible network latency between two EC2 instances in the same AZ and subnet. What feature provides the lowest achievable latency?', options: [{ id: 'A', text: 'Cluster placement group alone' }, { id: 'B', text: 'ENA Express (Scalable Reliable Datagram) — SRD protocol provides lower latency than standard TCP for EC2 east-west traffic' }, { id: 'C', text: 'Elastic Fabric Adapter (EFA)' }, { id: 'D', text: 'SR-IOV network passthrough' }], correct: ['B'], explanation: 'ENA Express uses the Scalable Reliable Datagram (SRD) protocol, which provides lower latency and higher bandwidth for single-flow communication between EC2 instances compared to standard TCP/ENA. Particularly effective for same-subnet traffic.', distractors: { A: 'Cluster placement group reduces physical distance but standard TCP/ENA latency still applies.', C: 'EFA is specifically for HPC/MPI workloads with OS-bypass — ENA Express improves standard socket applications.', D: 'SR-IOV is ENA\'s underlying technology — ENA Express is the specific feature for lower latency.' } },
  { id: 'd3-net-044', domain: 3, topics: ['Internet Gateway', 'egress only', 'IPv6'], type: 'single', stem: 'EC2 instances with IPv6 addresses need to initiate outbound connections to the internet but must not receive unsolicited inbound connections. What VPC component enables this?', options: [{ id: 'A', text: 'NAT Gateway (IPv4 only)' }, { id: 'B', text: 'Egress-Only Internet Gateway — allows outbound IPv6 traffic; blocks unsolicited inbound IPv6 from the internet' }, { id: 'C', text: 'Internet Gateway (allows both inbound and outbound)' }, { id: 'D', text: 'Virtual Private Gateway' }], correct: ['B'], explanation: 'Egress-Only Internet Gateway (EOIGW) is the IPv6 equivalent of NAT Gateway. IPv6 addresses are globally routable — EOIGW allows outbound IPv6 traffic while preventing unsolicited inbound connections. Similar to NAT for IPv4.', distractors: { A: 'NAT Gateway only supports IPv4 — not IPv6.', C: 'Internet Gateway allows both inbound and outbound — public IPv6 addresses would accept inbound connections.', D: 'VGW is for VPN connections — not internet access for IPv6.' } },
  { id: 'd3-net-045', domain: 3, topics: ['Network performance', 'exam trap', 'VPC peering bandwidth'], type: 'single', stem: 'Is there a bandwidth limit for VPC peering connections?', options: [{ id: 'A', text: 'Yes — VPC peering is limited to 1 Gbps per peering connection' }, { id: 'B', text: 'No explicit bandwidth limit — limited only by the instance network bandwidth of the communicating instances' }, { id: 'C', text: 'Yes — limited to 10 Gbps' }, { id: 'D', text: 'Bandwidth depends on whether it\'s intra-region or inter-region peering' }], correct: ['B'], explanation: 'VPC peering has no dedicated bandwidth limit. Throughput is bounded by the network bandwidth of the EC2 instances on each end. A 100 Gbps instance can use 100 Gbps of bandwidth over a peering connection.', distractors: { A: '1 Gbps is not a VPC peering limit — it\'s limited by instance bandwidth.', C: '10 Gbps is also not a VPC peering limit.', D: 'The bandwidth limit is instance-based, not determined by intra vs. inter-region peering type.' } },
]
